create table public.return_items (id uuid primary key default gen_random_uuid(), store_id uuid not null, return_id uuid not null, order_item_id uuid not null, quantity integer not null check(quantity>0), disposition text check(disposition in ('restock','damage','discard')), created_at timestamptz not null default now(), foreign key(store_id,return_id) references public.returns(store_id,id) on delete cascade, foreign key(store_id,order_item_id) references public.order_items(store_id,id), unique(return_id,order_item_id));
